1: //! Policy administration for the Settings page. Reads use /api/query, writes use
2: //! /api/command (or POST /api/admin/policies for creation). Every write carries the
3: //! concurrency values read from the projection, so stale actions are rejected by the
4: //! Worker. Tokens are memory only (Q-01).
5: 
6: use crate::users::UsersError;
7: use base64::Engine;
8: use serde::Deserialize;
9: use serde_json::{json, Value};
10: use std::time::Duration;
11: 
12: pub(crate) const API_BASE: &str = "https://onyx-framework.soheil-mozaffari.workers.dev";
13: 
14: #[derive(Clone)]
15: pub struct PolicyRow {
16:     pub id: String,
17:     pub name: String,
18:     pub status: String,
19:     pub version: i64,
20:     pub lifecycle_epoch: i64,
21:     pub authority_epoch: i64,
22: }
23: 
24: impl PolicyRow {
25:     /// The concurrency values a command needs, taken from the projection.
26:     pub fn concurrency(&self) -> Concurrency {
27:         Concurrency {
28:             id: self.id.clone(),
29:             version: self.version,
30:             lifecycle_epoch: self.lifecycle_epoch,
31:             authority_epoch: self.authority_epoch,
32:         }
33:     }
34: }
35: 
36: /// Target id and the three concurrency values a lifecycle command must carry.
37: #[derive(Clone)]
38: pub struct Concurrency {
39:     pub id: String,
40:     pub version: i64,
41:     pub lifecycle_epoch: i64,
42:     pub authority_epoch: i64,
43: }
44: 
45: #[derive(Deserialize)]
46: struct QueryResponse {
47:     data: Vec<Value>,
48: }
49: 
50: #[derive(Deserialize)]
51: struct CreatedPolicy {
52:     policy_id: String,
53: }
54: 
55: pub(crate) fn client() -> Result<reqwest::Client, UsersError> {
56:     reqwest::Client::builder()
57:         .timeout(Duration::from_secs(30))
58:         .build()
59:         .map_err(|_| UsersError::Failed)
60: }
61: 
62: pub(crate) fn check(status: reqwest::StatusCode) -> Result<(), UsersError> {
63:     if status == reqwest::StatusCode::FORBIDDEN {
64:         Err(UsersError::Forbidden)
65:     } else if status.is_success() {
66:         Ok(())
67:     } else {
68:         Err(UsersError::Failed)
69:     }
70: }
71: 
72: pub(crate) fn int(row: &Value, key: &str) -> Option<i64> {
73:     row.get(key).and_then(Value::as_i64)
74: }
75: 
76: /// Turns a query row (`id`, `version`, `lifecycle_epoch`, `authority_epoch`, `state`)
77: /// into a policy row. Returns `None` if a concurrency value is missing, so no command
78: /// can be sent with a guessed epoch.
79: fn to_policy(row: &Value) -> Option<PolicyRow> {
80:     let state = row.get("state").cloned().unwrap_or(Value::Null);
81:     Some(PolicyRow {
82:         id: row.get("id")?.as_str()?.to_string(),
83:         name: state.get("name").and_then(Value::as_str).unwrap_or("").to_string(),
84:         status: state.get("status").and_then(Value::as_str).unwrap_or("").to_string(),
85:         version: int(row, "version")?,
86:         lifecycle_epoch: int(row, "lifecycle_epoch")?,
87:         authority_epoch: int(row, "authority_epoch")?,
88:     })
89: }
90: 
91: fn envelope(query_type: &str, organization_id: &str, filters: Value) -> String {
92:     let body = json!({
93:         "query_id": uuid::Uuid::new_v4().to_string(),
94:         "query_type": query_type,
95:         "schema_version": "1.0",
96:         "organization_id": organization_id,
97:         "filters": filters,
98:         "limit": 100,
99:         "sort_order": "desc",
100:     });
101:     base64::engine::general_purpose::URL_SAFE_NO_PAD.encode(body.to_string())
102: }
103: 
104: pub(crate) async fn query(token: &str, organization_id: &str, query_type: &str, filters: Value) -> Result<Vec<Value>, UsersError> {
105:     let response = client()?
106:         .get(format!("{API_BASE}/api/query"))
107:         .query(&[("envelope", envelope(query_type, organization_id, filters))])
108:         .bearer_auth(token)
109:         .send()
110:         .await
111:         .map_err(|_| UsersError::Failed)?;
112:     check(response.status())?;
113:     let body: QueryResponse = response.json().await.map_err(|_| UsersError::Failed)?;
114:     Ok(body.data)
115: }
116: 
117: pub async fn list_policies(token: &str, organization_id: &str) -> Result<Vec<PolicyRow>, UsersError> {
118:     let rows = query(token, organization_id, "policy.list", json!({})).await?;
119:     Ok(rows.iter().filter_map(to_policy).collect())
120: }
121: 
122: /// Reads one policy's concurrency values for the detail panel. `None` if not found.
123: pub async fn policy_detail(token: &str, organization_id: &str, id: &str) -> Result<Option<PolicyRow>, UsersError> {
124:     let rows = query(token, organization_id, "policy.detail", json!({ "target_id": id })).await?;
125:     Ok(rows.iter().find(|r| r.get("id").and_then(Value::as_str) == Some(id)).and_then(to_policy))
126: }
127: 
128: /// Creates a policy. Sends one Idempotency-Key per user action, so a retry cannot
129: /// create a second policy.
130: pub async fn create_policy(token: &str, name: &str, idempotency_key: &str) -> Result<String, UsersError> {
131:     let response = client()?
132:         .post(format!("{API_BASE}/api/admin/policies"))
133:         .bearer_auth(token)
134:         .header("Idempotency-Key", idempotency_key)
135:         .json(&json!({ "name": name }))
136:         .send()
137:         .await
138:         .map_err(|_| UsersError::Failed)?;
139:     check(response.status())?;
140:     let created: CreatedPolicy = response.json().await.map_err(|_| UsersError::Failed)?;
141:     Ok(created.policy_id)
142: }
143: 
144: /// Sends one lifecycle command. Names follow the Worker: `target_type` is "policy" or
145: /// "legal_hold"; `command_type` is e.g. "policy.PublishPolicyVersion" or "ReleaseLegalHold".
146: /// Returns the Worker's JSON result.
147: pub async fn send_command(
148:     token: &str,
149:     organization_id: &str,
150:     target_type: &str,
151:     command_type: &str,
152:     target: &Concurrency,
153:     payload: Value,
154: ) -> Result<Value, UsersError> {
155:     let envelope = json!({
156:         "command_id": uuid::Uuid::new_v4().to_string(),
157:         "operation_id": uuid::Uuid::new_v4().to_string(),
158:         "command_type": command_type,
159:         "schema_version": "1.0",
160:         "target": { "id": target.id, "type": target_type, "organization_id": organization_id },
161:         "expected_version": target.version,
162:         "expected_lifecycle_epoch": target.lifecycle_epoch,
163:         "expected_authority_epoch": target.authority_epoch,
164:         "issued_at": chrono::Utc::now().to_rfc3339(),
165:         "vector_clock": { "entries": {} },
166:         "correlation_id": uuid::Uuid::new_v4().to_string(),
167:         "causation_id": null,
168:         "payload": payload,
169:     });
170:     let response = client()?
171:         .post(format!("{API_BASE}/api/command"))
172:         .bearer_auth(token)
173:         .json(&envelope)
174:         .send()
175:         .await
176:         .map_err(|_| UsersError::Failed)?;
177:     check(response.status())?;
178:     response.json().await.map_err(|_| UsersError::Failed)
179: }
180: 
181: /// Turns an entered rule value into JSON: true/false, a number, or text.
182: pub fn parse_rule_value(raw: &str) -> Value {
183:     match raw {
184:         "true" => Value::Bool(true),
185:         "false" => Value::Bool(false),
186:         _ => raw
187:             .parse::<i64>()
188:             .map(Value::from)
189:             .or_else(|_| raw.parse::<f64>().map(Value::from))
190:             .unwrap_or_else(|_| Value::String(raw.to_string())),
191:     }
192: }

