1: //! Legal holds for the Settings page: read one hold, apply a hold to a target, and
2: //! release an applied hold. Apply uses the dedicated REST route with an Idempotency-Key;
3: //! release is a command carrying the projection's concurrency values. Tokens are memory
4: //! only (Q-01).
5: 
6: use crate::policy::{self, Concurrency};
7: use crate::users::UsersError;
8: use serde::Deserialize;
9: use serde_json::{json, Value};
10: 
11: #[derive(Clone)]
12: pub struct HoldRow {
13:     pub status: String,
14:     pub concurrency: Concurrency,
15: }
16: 
17: #[derive(Deserialize)]
18: struct CreatedHold {
19:     legal_hold_id: String,
20: }
21: 
22: /// Turns a query row into a hold. `None` if a concurrency value is missing, so no
23: /// release can be sent with a guessed epoch.
24: fn to_hold(row: &Value) -> Option<HoldRow> {
25:     let id = row.get("id")?.as_str()?.to_string();
26:     let state = row.get("state").cloned().unwrap_or(Value::Null);
27:     Some(HoldRow {
28:         status: state.get("status").and_then(Value::as_str).unwrap_or("").to_string(),
29:         concurrency: Concurrency {
30:             id,
31:             version: policy::int(row, "version")?,
32:             lifecycle_epoch: policy::int(row, "lifecycle_epoch")?,
33:             authority_epoch: policy::int(row, "authority_epoch")?,
34:         },
35:     })
36: }
37: 
38: /// Reads one hold. `None` if it does not exist in this organization.
39: pub async fn hold_detail(token: &str, organization_id: &str, id: &str) -> Result<Option<HoldRow>, UsersError> {
40:     let rows = policy::query(token, organization_id, "legal_hold.detail", json!({ "target_id": id })).await?;
41:     Ok(rows
42:         .iter()
43:         .find(|r| r.get("id").and_then(Value::as_str) == Some(id))
44:         .and_then(to_hold))
45: }
46: 
47: /// Applies a hold and returns the new hold id. One Idempotency-Key per user action.
48: pub async fn apply(
49:     token: &str,
50:     target_id: &str,
51:     target_type: &str,
52:     reason: &str,
53:     idempotency_key: &str,
54: ) -> Result<String, UsersError> {
55:     let response = policy::client()?
56:         .post(format!("{}/api/admin/legal-holds", policy::API_BASE))
57:         .bearer_auth(token)
58:         .header("Idempotency-Key", idempotency_key)
59:         .json(&json!({ "target_id": target_id, "target_type": target_type, "reason": reason }))
60:         .send()
61:         .await
62:         .map_err(|_| UsersError::Failed)?;
63:     policy::check(response.status())?;
64:     let created: CreatedHold = response.json().await.map_err(|_| UsersError::Failed)?;
65:     if created.legal_hold_id.is_empty() {
66:         return Err(UsersError::Failed);
67:     }
68:     Ok(created.legal_hold_id)
69: }
70: 
71: /// Releases an applied hold. The Worker's command name is `ReleaseLegalHold`.
72: pub async fn release(token: &str, organization_id: &str, hold: &HoldRow, reason: &str) -> Result<(), UsersError> {
73:     policy::send_command(
74:         token,
75:         organization_id,
76:         "legal_hold",
77:         "ReleaseLegalHold",
78:         &hold.concurrency,
79:         json!({ "reason": reason }),
80:     )
81:     .await
82:     .map(|_| ())
83: }

