96: /// Maps a failure to catalog text. Network and server failures use existing
97: /// catalog wording; a dedicated "sign-in failed, try again" key is not in the
98: /// catalog yet.
99: fn error_text(lang: Lang, error: LoginError) -> &'static str {
100:     match error {
101:         LoginError::InvalidCredentials => text(lang, "auth.adminInvalidCredentials"),
102:         LoginError::Timeout | LoginError::Network => text(lang, "common.connectionLost"),
103:         LoginError::Server { .. } | LoginError::InvalidResponse => text(lang, "status.failed"),
104:     }
105: }
