107: /// Runs one Users write on a worker thread, then reloads the list on success.
108: fn run_user_write<F, Fut>(
109:     weak: slint::Weak<AppWindow>,
110:     session: Arc<Mutex<Option<AdminSession>>>,
111:     lang: Lang,
112:     action: F,
113: ) where
114:     F: FnOnce(String) -> Fut + Send + 'static,
115:     Fut: std::future::Future<Output = Result<(), UsersError>>,
116: {
117:     let token = match session
118:         .lock()
119:         .ok()
120:         .and_then(|slot| slot.as_ref().map(|s| s.access_token().to_owned()))
121:     {
