161: /// Runs one Organizations call on a worker thread. `done` runs on the UI thread
162: /// with the result, so reads can fill the screen and writes can reload it.
163: fn run_org_call<T, F, Fut, D>(
164:     weak: slint::Weak<AppWindow>,
165:     session: SessionSlot,
166:     lang: Lang,
167:     action: F,
168:     done: D,
169: ) where
170:     T: Send + 'static,
171:     F: FnOnce(String) -> Fut + Send + 'static,
172:     Fut: std::future::Future<Output = Result<T, UsersError>>,
173:     D: FnOnce(slint::Weak<AppWindow>, SessionSlot, Lang, Result<T, UsersError>) + Send + 'static,
174: {
175:     let token = match session
176:         .lock()
177:         .ok()
178:         .and_then(|slot| slot.as_ref().map(|s| s.access_token().to_owned()))
179:     {
180:         Some(token) => token,
181:         None => return,
182:     };
183:     if let Some(ui) = weak.upgrade() {
184:         ui.set_users_loading(true);
185:         ui.set_users_error("".into());
186:     }
187:     std::thread::spawn(move || {
188:         let result = tokio::runtime::Builder::new_current_thread()
189:             .enable_all()
190:             .build()
191:             .map_err(|_| UsersError::Failed)
192:             .and_then(|rt| rt.block_on(action(token)));
193:         let _ = slint::invoke_from_event_loop(move || {
194:             if let Some(ui) = weak.upgrade() {
195:                 ui.set_users_loading(false);
196:             }
197:             done(weak, session, lang, result);
198:         });
199:     });
200: }
