424: /// Sends one lifecycle command to the selected policy, then reloads the list and detail.
425: fn policy_command(
426:     weak: slint::Weak<AppWindow>,
427:     session: SessionSlot,
428:     lang: Lang,
429:     selected: SelectedPolicy,
430:     command: &'static str,
431:     payload: serde_json::Value,
432:     pending: PendingRules,
433: ) {
434:     let Some(org) = org_id_of(&session) else { return };
435:     let Some(row) = selected.lock().ok().and_then(|slot| slot.clone()) else { return };
436:     let pending_done = pending.clone();
437:     let id = row.id.clone();
438:     let concurrency = row.concurrency();
439:     let reload = selected.clone();
440:     run_org_call(
441:         weak,
442:         session,
443:         lang,
444:         move |token| async move { policy::send_command(&token, &org, "policy", command, &concurrency, payload).await },
445:         move |weak, session, lang, result| {
446:             let Some(ui) = weak.upgrade() else { return };
447:             match result {
448:                 Ok(response) => {
449:                     if command == "policy.CreatePolicyVersion" {
450:                         if let Ok(mut rules) = pending_done.lock() {
451:                             rules.clear();
452:                         }
453:                         ui.set_rules_pending(0);
454:                     }
455:                     let status = if command == "policy.EvaluatePolicy" {
456:                         format_evaluation(lang, &response)
457:                     } else {
458:                         String::new()
459:                     };
460:                     ui.set_policy_status(status.into());
461:                     load_policies(weak.clone(), session.clone(), lang);
462:                     load_policy_detail(weak, session, lang, id, reload);
463:                 }
464:                 Err(error) => show_policy_error(&ui, lang, error),
465:             }
