599: fn main() -> Result<(), slint::PlatformError> {
600:     let ui = AppWindow::new()?;
601:     apply_language(&ui, Lang::En);
602:     let lang = Rc::new(Cell::new(Lang::En));
603:     // Memory-only session slot (Q-01): never written to disk or the keyring.
604:     let session: Arc<Mutex<Option<AdminSession>>> = Arc::new(Mutex::new(None));
605: 
606:     let weak = ui.as_weak();
607:     let lang_for_switch = lang.clone();
608:     ui.on_select_language(move |tag| {
609:         // An unsupported tag is ignored and the current language stays active.
610:         if let (Some(ui), Some(new_lang)) = (weak.upgrade(), Lang::from_tag(&tag)) {
611:             lang_for_switch.set(new_lang);
612:             apply_language(&ui, new_lang);
613:         }
614:     });
615: 
616:     let sign_out_session = session.clone();
617:     let page_session = session.clone();
618:     let page_lang = lang.clone();
619:     let write_lang = lang.clone();
620:     let write_session = session.clone();
621:     let weak = ui.as_weak();
622:     ui.on_sign_in(move |username, password| {
623:         let Some(ui) = weak.upgrade() else { return };
624:         if ui.get_busy() {
625:             return;
626:         }
627:         ui.set_busy(true);
628:         ui.set_error_text("".into());
629: 
630:         let current_lang = lang.get();
631:         let username = username.to_string();
632:         let password = password.to_string();
633:         let request_id = new_request_id();
634:         let weak = weak.clone();
635:         let session = session.clone();
636: 
637:         std::thread::spawn(move || {
638:             let result = tokio::runtime::Builder::new_current_thread()
639:                 .enable_all()
640:                 .build()
641:                 .map_err(|_| LoginError::Network)
642:                 .and_then(|rt| rt.block_on(auth::sign_in(&username, &password, &request_id)));
643: 
644:             let _ = slint::invoke_from_event_loop(move || {
645:                 let Some(ui) = weak.upgrade() else { return };
646:                 ui.set_busy(false);
647:                 match result {
648:                     Ok(new_session) => {
649:                         ui.set_signed_in_as(new_session.username.clone().into());
650:                         // Client-side UX only: the Worker remains the authorization boundary.
651:                         ui.set_is_all_father(new_session.role == "ALL_FATHER");
652:                         ui.set_page(0);
653:                         ui.set_signed_in(true);
654:                         if let Ok(mut slot) = session.lock() {
655:                             *slot = Some(new_session);
656:                         }
657:                         load_users(ui.as_weak(), session.clone(), current_lang);
658:                     }
659:                     Err(error) => ui.set_error_text(error_text(current_lang, error).into()),
660:                 }
661:             });
662:         });
663:     });
664: 
665:     let users_weak = ui.as_weak();
666:     ui.on_select_page(move |page| {
667:         if page == 0 {
668:             load_users(users_weak.clone(), page_session.clone(), page_lang.get());
669:         } else if page == 1 {
670:             load_mobile_access(users_weak.clone(), page_session.clone(), page_lang.get());
671:             load_policies(users_weak.clone(), page_session.clone(), page_lang.get());
672:         } else if page == 2 {
673:             load_profiles(users_weak.clone(), page_session.clone(), page_lang.get());
674:         } else if page == 3 {
675:             load_orgs(users_weak.clone(), page_session.clone(), page_lang.get());
676:         }
677:     });
678: 
679:     let session = sign_out_session;
680:     let weak = ui.as_weak();
681:     ui.on_sign_out(move || {
682:         // Dropping the session clears the in-memory tokens.
683:         if let Ok(mut slot) = session.lock() {
684:             *slot = None;
685:         }
686:         if let Some(ui) = weak.upgrade() {
687:             ui.set_signed_in(false);
688:             ui.set_is_all_father(false);
689:             ui.set_signed_in_as("".into());
690:             ui.set_error_text("".into());
691:         }
692:     });
693: 
