pub fn evaluation_view(lang: Lang, response: &Value) -> Option<EvaluationView> {
    let evaluation = response.pointer("/result/command_result")?;
    let version = evaluation.get("evaluated_version").and_then(Value::as_i64).map(|v| v.to_string()).unwrap_or_default();
    let rule_found = evaluation.get("rule_found").and_then(Value::as_bool);
    let (shown, detail) = if rule_found == Some(false) {
        (text(lang, "settings.ruleNotFound").to_string(), String::new())
    } else {
        match evaluation.get("result") {
            None | Some(Value::Null) => (text(lang, "settings.noValueDefined").to_string(), String::new()),
            Some(Value::String(value)) => (value.clone(), String::new()),
            Some(value @ (Value::Object(_) | Value::Array(_))) => {
                let compact = value.to_string();
                let detail = serde_json::to_string_pretty(value).unwrap_or_else(|_| compact.clone());
                (compact, detail)
            }
            Some(other) => (other.to_string(), String::new()),
        }
    };
    Some(EvaluationView {
        summary: format!("{}: {} · {}: {}", text(lang, "settings.evaluationResult"), shown, text(lang, "settings.policyVersion"), version),
        detail,
    })
}
